<script setup lang="ts">
import {onMounted,ref} from 'vue';
import {api} from '../services/api';
import {useAccountStore} from '../stores/account';
import AppHeader from '../components/AppHeader.vue';
import AppState from '../components/AppState.vue';
import {profilePayload} from '../services/profileFacts';

const account=useAccountStore();
const interests=ref<string[]>([]);
const categoryLabels:Record<string,string>={academic:'教务',award:'奖助评优',exam:'考试',competition:'竞赛',career:'就业实习',research:'科研申报',other:'其他'};
async function saveInterests(){saving.value=true;error.value='';try{await api('/api/v1/profile/interests',{method:'PUT',body:JSON.stringify({categories:interests.value})});message.value='关注分类已保存，只影响软偏好，不改变资格判断。'}catch(e:any){error.value=e.message}finally{saving.value=false}}

const rankValidUntil=ref(''),history=ref<any[]>([]);
const profile=ref<any>({student_type:'',enrollment_year:null,college:'',major:'',class_name:'',rank_percent:null,team_size:null,graduation_year:null,certificate_level:null,role:'',moral_score:null,advisor_count:null,participation_count:null,disciplinary_status:'',coursework_status:'',fitness_status:'',moral_bonus_items:''});
const completeness=ref<any>(null),loading=ref(false),saving=ref(false),error=ref(''),message=ref('');
const labels:Record<string,string>={student_type:'身份',enrollment_year:'入学年份',college:'学院',major:'专业',class_name:'班级',rank_percent:'排名比例',team_size:'团队人数',certificate_level:'证书等级',graduation_year:'毕业年份',role:'角色',moral_score:'德育成绩',advisor_count:'指导教师人数',participation_count:'历次参赛次数',disciplinary_status:'处分记录',coursework_status:'课程合格情况',fitness_status:'体育测试情况',moral_bonus_items:'德育加分项目'};
onMounted(load);
async function load(){if(!account.signedIn)return;loading.value=true;error.value='';try{const saved=await api('/api/v1/profile');const meta=await api('/api/v1/profile/meta');const until=meta.field_valid_until?.rank_percent;if(until){const date=new Date(until);rankValidUntil.value=`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`}profile.value={...profile.value,...saved,moral_bonus_items:Array.isArray(saved.moral_bonus_items)?saved.moral_bonus_items.join('、'):saved.moral_bonus_items||''};completeness.value=await api('/api/v1/profile/completeness');const rows=await api('/api/v1/profile/history');history.value=Array.isArray(rows)?rows:[];const preferences=await api('/api/v1/profile/interests');interests.value=Array.isArray(preferences.categories)?preferences.categories:[]}catch(e:any){error.value=e?.message||'个人画像读取失败'}finally{loading.value=false}}
async function save(){saving.value=true;error.value='';message.value='';try{await api('/api/v1/profile',{method:'PUT',body:JSON.stringify({...profilePayload(profile.value),valid_until:rankValidUntil.value?{rank_percent:new Date(rankValidUntil.value+'T23:59:59').toISOString()}: {}})});completeness.value=await api('/api/v1/profile/completeness');account.completeness=completeness.value;message.value='个人画像已保存，已有事项的相关性已按最新资料重新计算。'}catch(e:any){error.value=e?.message||'个人画像保存失败'}finally{saving.value=false}}
</script>

<template><div class="page page--utility"><AppHeader title="个人画像"><template #action><RouterLink class="icon-button icon-button--plain" to="/me" aria-label="返回">←</RouterLink></template></AppHeader><div v-if="error" class="notice notice--danger">{{error}}</div><div v-if="message" class="notice notice--success">{{message}}</div><AppState v-if="!account.signedIn" title="登录后完善个人画像" description="画像数据按账户隔离，并用于资格规则判断。"><RouterLink class="button button--primary" to="/auth/login">登录</RouterLink></AppState><AppState v-else-if="loading" kind="loading" title="正在读取个人画像"/><template v-else><section v-if="completeness" class="profile-completeness"><div><span class="text-label">当前规则资料完整度</span><strong>{{completeness.score}}%</strong></div><span class="progress-track"><i :style="{width:`${completeness.score}%`}"></i></span><p v-if="completeness.missing_fields.length">当前事项规则还需要：{{completeness.missing_fields.map((field:string)=>labels[field]||field).join('、')}}</p><p v-else>当前事项规则需要的画像资料已填写完整。</p></section><form class="surface-card form-card" @submit.prevent="save"><label>身份<select v-model="profile.student_type"><option value="">请选择</option><option value="undergraduate">本科生</option><option value="graduate">研究生</option><option value="teacher">教师</option><option value="other">其他</option></select></label><div class="form-grid"><label>入学年份<input v-model.number="profile.enrollment_year" type="number" min="1990" max="2100"></label><label>毕业年份<input v-model.number="profile.graduation_year" type="number" min="1990" max="2100" placeholder="可留空"></label></div><label>学院<input v-model="profile.college" placeholder="所在学院"></label><label>专业<input v-model="profile.major" placeholder="所学专业"></label><label>班级<input v-model="profile.class_name" placeholder="可留空"></label><div class="form-grid"><label>排名百分比<input v-model.number="profile.rank_percent" type="number" min="0" max="100" placeholder="未知可留空"></label><label>团队人数<input v-model.number="profile.team_size" type="number" min="1" placeholder="未知可留空"></label></div><div class="form-grid"><label>证书等级<input v-model.number="profile.certificate_level" type="number" min="0" placeholder="按通知口径填写"></label><label>角色<input v-model="profile.role" placeholder="如班委、队长"></label></div><div class="form-grid"><label>德育成绩<input v-model.number="profile.moral_score" type="number" min="0" max="100"></label><label>指导教师人数<input v-model.number="profile.advisor_count" type="number" min="0" max="100"></label><label>当前赛事历次参赛次数<input v-model.number="profile.participation_count" type="number" min="0" max="100"></label></div><p>按当前通知口径填写；自述资料不等于官方资格证明。</p><label>处分记录<select v-model="profile.disciplinary_status"><option value="">待补充</option><option value="clear">无记录 / 合格</option><option value="recorded">有记录 / 不合格</option></select></label><label>通知要求的课程是否全部合格<select v-model="profile.coursework_status"><option value="">待补充</option><option value="passed">无记录 / 合格</option><option value="failed">有记录 / 不合格</option></select></label><label>通知要求的体育测试是否合格<select v-model="profile.fitness_status"><option value="">待补充</option><option value="passed">无记录 / 合格</option><option value="failed">有记录 / 不合格</option></select></label><label>排名资料有效至（选填）<input v-model="rankValidUntil" type="date"></label><p>到期后排名按未知处理，需重新填写；历史记录保留。</p><label>德育加分项目<input v-model="profile.moral_bonus_items" placeholder="多个项目用顿号分隔"></label><button class="button button--primary button--block" :disabled="saving">{{saving?'保存中…':'保存画像'}}</button><p class="capability-note">完整度与当前账户规则读取同一组 Profile facts；通知原文不足会单独提示，不会归因于画像。</p></form><section class="surface-card"><h2>关注分类</h2><p>由你填写，仅用于软偏好；不会覆盖资格不符或资料不足。</p><label v-for="(label,category) in categoryLabels" :key="category" class="consent-row"><input v-model="interests" type="checkbox" :value="category">{{label}}</label><button class="button button--secondary" :disabled="saving" @click="saveInterests">保存关注分类</button></section><details class="surface-card"><summary>资料填写历史（最近500条）</summary><p v-for="row in history" :key="row.id">{{labels[row.key.replace('profile.','')]||row.key}} · {{row.created_at}} · {{row.valid_until?'有效至 '+row.valid_until:'未声明有效期'}}</p></details></template></div></template>
